const W = 1800;
const H = ~~(W/2*3);
const S = 20;
let nSeedm, rSeed;
let pal1, pal2, pal3;

// https://looka.com/blog/color-combinations/
let palettes = [
	["#B2456E", "#FBEAE7", "#552619"],
	["#EDF4F2", "#7C8363", "#31473A"],
	["#CADCFC", "#8AB6F9", "#00246B"],
	["#D9DAD9", "#68A4A5", "#4C8055"]
/*
	"#264653", "#2A9D8F", "#E9C46A", "#F4A261", 
  "#E76F51", "#D62828", "#023047", "#8A5A44", 
  "#4A4E69", "#9A8C98", "#C9ADA7", "#5A189A", 
  "#10002B", "#6A0572", "#FF6F61", "#8D99AE"
*/
]; // .map((c) => c+"C0");

function setup() {
  createCanvas(W, H);
	describe("texture of colored shapes different sizes and colors by noise");

	nSeed = ~~random(2349875);
	rSeed = ~~random(2349875);

	let pals = [];
	for (let i = 0; i < palettes.length; i++) pals[i] = i;
	shuffle(pals, true);
	pal1 = palettes[pals.shift()]
	shuffle(pals, true);
	pal2 = palettes[pals.shift()]
	shuffle(pals, true);
	pal3 = palettes[pals.shift()]

  loop();
}

function draw() {
  background("black")
  noStroke();
	fill("beige")
	rect(0, 0, width, height);
	shuffle(pal1, true);
	shuffle(pal2, true);
	shuffle(pal3, true);

  // noiseDetail(8, 0.65);
	noiseDetail(
		~~map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 2, 12), 
		map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0, 0.75)
	);
	noiseDetail(8, 0.65);
	// const nSeed = ~~random(2349875);
	// const rSeed = ~~random(2349875);
	console.log(`nSeed: ${nSeed}, rSeed ${rSeed}`);
  noiseSeed(nSeed);
  randomSeed(rSeed);

	for (let rpt = 0; rpt < 2; rpt++)
	for (let x = S*2; x < width-S; x += S) {
    for (let y = S*2; y < height-S; y += S) {
      const sze = map(noise(x * 0.1, y * 0.1), 0, 1, S*0.25, S*1.5);
      const noiseVal1 = noise(x * 0.001, y * 0.0006);
      const noiseVal2 = noise(x * 0.002, y * 0.0008);
      const noiseVal3 = noise(x * 0.003, y * 0.001);
      const colorIdx1 = ~~(noiseVal1 * pal1.length) % pal1.length; //  ~~(noiseVal1 * colors.length) % colors.length;
      const colorIdx2 = ~~(noiseVal2 * pal2.length) % pal2.length;
      const colorIdx3 = ~~(noiseVal3 * pal3.length) % pal3.length;
      const mixCol = lerpColor(
        color(pal1[colorIdx1]), // color(colors[colorIdx1]),
        color(pal2[colorIdx2]), // color(colors[colorIdx2]),
        noiseVal1
      ); 

			// with a lower chance (noise()-0.2) mix to 3rd palette
			const noiseVal4 = constrain(noise(12.3 + x * 0.0321, 34.1 + y * 0.0231) - 0.2, 0, 1);
      const col = lerpColor(
        mixCol,
        color(pal3[colorIdx3]), // color(colors[colorIdx3]),
        easeInOutQuint(noiseVal4)
      ); // Final color mix with third color

			fill(col);
			// circle(x, y, 4)

			push();
			translate(x, y);
			rotate(noise(12.3 + x * 0.0321, 34.1 + y * 0.0231)-0.5); // random(-0.5, 0.5)
      beginShape();
			const nEdges = ~~random(3, 6);
      for (let i = 0; i < nEdges; i++) {
        const angle = (TWO_PI / nEdges) * i;
        const sx = cos(angle) * sze + map(noise(x * 0.1 + i, y * 0.1 + i), 0, 1, -S/4, S/4);
        const sy = sin(angle) * sze + map(noise(x * 0.1 + i, y * 0.1 + i), 0, 1, -S/4, S/4);
        vertex(sx, sy);
      }
      endShape(CLOSE);
			pop();
    } // x
  } // y
	// // noLoop() removed for animation
}

function easeInOutQuint(x) {
  return x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2;
}

function mousePressed() {
	if (mouseButton == LEFT) setup();
}

function keyPressed() {
	if (key === "s") {
		const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  	saveCanvas(`texture_${timestamp}`);
	}
}
